Bug hunt: this virtual-scroll offset function shows blank rows when scrolled to the bottom. Reproduce, then repair.

export function getWindow(scrollTop, rowHeight, viewport, total) {
  const start = Math.floor(scrollTop / rowHeight);
  const visible = Math.ceil(viewport / rowHeight);
  const end = start + visible;
  return { start, end, padTop: start * rowHeight, padBottom: (total - end) * rowHeight };
}

