import { getWindow } from '../src/window.js';

// Invariant helper: padTop + rendered height + padBottom === total * rowHeight,
// and the window never references rows outside [0, total].
function checkInvariant(scrollTop, rowHeight, viewport, total) {
  const w = getWindow(scrollTop, rowHeight, viewport, total);
  const start = Math.floor(scrollTop / rowHeight);
  // Rows actually needed on screen: fractional first row + viewport coverage.
  const expectedEnd = Math.min(total, Math.ceil((scrollTop + viewport) / rowHeight));
  expect(w.start).toBe(start);
  expect(w.end).toBe(expectedEnd);
  expect(w.start).toBeGreaterThanOrEqual(0);
  expect(w.end).toBeLessThanOrEqual(total);
  const rendered = (w.end - w.start) * rowHeight;
  expect(w.padTop + rendered + w.padBottom).toBe(total * rowHeight);
  return w;
}

describe('getWindow', () => {
  it('defect 1: clamps end to total so padBottom is never negative at the bottom', () => {
    // total=10 rows of 20px; scrolled fully to bottom (scrollTop=200).
    // Buggy code: start=10, visible=5 -> end=15 > total, padBottom=-100.
    const w = getWindow(200, 20, 100, 10);
    expect(w.end).toBeLessThanOrEqual(10);
    expect(w.padBottom).toBeGreaterThanOrEqual(0);
    expect(w.padBottom).toBe(0);
  });

  it('defect 2: counts the partially visible first row when scrollTop is mid-row', () => {
    // rowHeight=20, scrollTop=15 (mid-row), viewport=60 => rows 0..3 are
    // visible (rows 1,2,3 fully plus half of row 0 and half of row 4? no:
    // pixels 15..75 touch rows 0,1,2,3). Buggy code undercounts via
    // ceil(viewport/rowHeight)=3 from start=0, cutting off the last touched row.
    const w = getWindow(15, 20, 60, 100);
    // Last pixel (74.99) falls in row floor(75/20)=3, so end must cover row 3.
    expect(w.end).toBeGreaterThanOrEqual(4); // rows 0..3 => end >= 4
    expect(w.padTop).toBe(15 - (15 % 20)); // 0 here, but derived from start
  });

  it('loop: invariant holds over 500 random scroll positions', () => {
    // Deterministic PRNG so failures are reproducible.
    let seed = 42;
    const rand = () => {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      return seed / 2147483648;
    };
    for (let i = 0; i < 500; i++) {
      const rowHeight = 10 + Math.floor(rand() * 40);
      const total = 1 + Math.floor(rand() * 500);
      const maxScroll = Math.max(0, total * rowHeight);
      const scrollTop = rand() < 0.2 ? maxScroll : rand() * maxScroll; // bias toward the bottom edge
      const viewport = 50 + rand() * 800;
      checkInvariant(scrollTop, rowHeight, viewport, total);
    }
  });
});
"})
