  // Clamp start so scrolling past the content can't push the window past the last row.
  const start = Math.min(Math.floor(scrollTop / rowHeight), total);
  // +1 semantics come from measuring the viewport in absolute pixels:
  // a mid-row scrollTop means the first row is only partially covered, and
  // ceil((scrollTop + viewport) / rowHeight) counts every touched row exactly.
  const end = Math.min(total, Math.max(start, Math.ceil((scrollTop + viewport) / rowHeight)));
  return { start, end, padTop: start * rowHeight, padBottom: (total - end) * rowHeight };
}
